typestate.code:
//! Typestate of a container's lifecycle (Sprint 5 — Damas: *correctness by
//! construction*). The states are **types**, and the illegal transitions **do not
//! compile** — instead of being caught (or not) at runtime by a `match` over
//! a [`Status`].
//!
//! The model: `Created → Running → Stopped → (restart) Created`. Each transition
//! **consumes** the previous phase, so an obsolete phase cannot be reused.
//!
//! ```
//! use delonix_model::typestate::Phase;
//! use delonix_model::records::Status;
//!
//! let created = Phase::new("abc123");            // Phase<Created>
//! assert_eq!(created.status(), Status::Created);
//! let running = created.start(4242);             // Created → Running
//! assert_eq!(running.pid(), 4242);
//! let stopped = running.stop(0);                 // Running → Stopped
//! assert_eq!(stopped.status(), Status::Stopped);
//! let _again = stopped.restart();                // Stopped → Created (reuses the id)
//! ```
//!
//! The invalid transitions are **compilation errors**, not runtime bugs:
//!
//! ```compile_fail
//! use delonix_model::typestate::Phase;
//! let created = Phase::new("abc123"); // Phase<Created>
//! created.stop(0);                    // ERROR: `stop` only exists on Phase<Running>
//! ```
//!
//! ```compile_fail
//! use delonix_model::typestate::Phase;
//! let running = Phase::new("abc123").start(1); // Phase<Running>
//! running.start(2);                            // ERROR: `start` only exists on Phase<Created>
//! ```
//!
//! ```compile_fail
//! use delonix_model::typestate::Phase;
//! let created = Phase::new("abc123");
//! let _running = created.start(1);
//! created.start(2);                  // ERROR: `created` was consumed by the 1st transition
//! ```

use crate::records::Status;
use std::marker::PhantomData;

/// State: created, still without a `pid`.
pub struct Created;
/// State: running, with a live init `pid`.
pub struct Running;
/// State: terminated, with an exit code.
pub struct Stopped;

/// A **typed** phase of the lifecycle. The `S` parameter is the current state; the
/// transition methods only exist in the phases where they are valid.
pub struct Phase<S> {
    id: String,
    pid: Option<i32>,
    code: Option<i32>,
    _state: PhantomData<S>,
}

verify-digest.code:
/// When `reference` names a content digest (`sha256:...`), verifies the fetched
/// manifest bytes hash to EXACTLY that digest. A digest-pinned pull
/// (`repo@sha256:...`) is the whole point of pinning: even a compromised or
/// MITM'd registry must not be able to substitute the content. The blobs are
/// already checked against the digests the manifest declares — but if the
/// manifest ITSELF is not checked against the pinned reference, the registry
/// can serve a completely different, internally-consistent manifest (pointing
/// at the attacker's blobs) and the pin becomes decorative. The chain of trust
/// for a digest pull rests entirely on this check. A tag reference (`:latest`)
/// has no digest to verify, so it is a no-op there — TLS is the only integrity
/// for tags, same as `docker pull`.
fn verify_manifest_digest(reference: &str, manifest_bytes: &[u8]) -> Result<()> {
    if let Some(want) = reference.strip_prefix("sha256:") {
        let got = sha256_hex(manifest_bytes);
        if !got.eq_ignore_ascii_case(want) {
            return Err(Error::DigestMismatch(format!(
                "manifest digest mismatch: reference pins sha256:{want} but the registry \
                 served a manifest hashing to sha256:{got} — refusing (possible compromised \
                 registry or MITM)"
            )));
        }
    }
    Ok(())
}

safe-bind-target.code:
/// Resolves `target` (an in-container path, already lexically validated by
/// `mount_target_safe`) against `rootfs`, component-by-component, refusing to
/// descend through any symlink an image layer may have planted along the
/// way. `mount_target_safe`'s lexical `..` check is not enough on its own:
/// `create_dir_all`/`OpenOptions::open` (called on the joined path right
/// after this) FOLLOW symlinks, and `bind_volume` runs BEFORE `pivot_root`
/// while `/` is still the real host filesystem — an absolute symlink at ANY
/// path component (a malicious image shipping e.g. `/etc -> /root`, or the
/// final mount-target component itself already existing as one) redirects
/// the destination to an arbitrary real host path, and the subsequent
/// create/open then create real directories/files on the host, as the
/// engine's own uid. Mirrors the confinement technique `cmd::build::
/// confine_to` already uses for the build's COPY (a sibling of this exact
/// bug class, fixed there first) — this is the engine-side equivalent.
fn safe_bind_target(rootfs: &str, target: &str) -> Option<std::path::PathBuf> {
    let mut current = std::path::PathBuf::from(rootfs);
    for comp in std::path::Path::new(target).components() {
        let std::path::Component::Normal(c) = comp else {
            continue;
        };
        current.push(c);
        if let Ok(meta) = std::fs::symlink_metadata(&current) {
            if meta.file_type().is_symlink() {
                return None;
            }
        }
    }
    Some(current)
}

exit-codes.code:
/// The single place an engine error becomes an exit code.
///
/// Pure on purpose: two places deciding the same number is how they start
/// disagreeing, and a table this small is only worth anything if it is the
/// whole truth.
pub fn for_error(e: &Error) -> i32 {
    match e {
        Error::NotFound(_) | Error::VmNotFound(_) => NOT_FOUND,
        Error::NotRunning(_) => NOT_RUNNING,
        Error::Conflict(_) => CONFLICT,
        Error::Unavailable(_) => UNAVAILABLE,
        Error::Timeout(_) => TIMEOUT,
        Error::Coded { inner, .. } => for_error(inner),
        // The KIND is inspected rather than the variant: `Error::Io` is the
        // wrapper every filesystem refusal arrives in, and EACCES inside it is
        // a different answer for the caller than a full disk or a bad path.
        Error::Io(e) if e.kind() == std::io::ErrorKind::PermissionDenied => NO_PERMISSION,
        Error::Io(_) => IO,
        Error::Json(_) | Error::Runtime { .. } => GENERIC,
        Error::Invalid(_) | Error::Registry(_) => GENERIC,
    }
}

store-update.code:
/// **Safe read-modify-write** of an item: locks (`flock`), re-reads the
/// state ALREADY under the lock, applies `f` and writes — same pattern as
/// [`Store::update`], generalized to any `JsonStore<T>`.
///
/// Use this (and not `load` + mutate + `save`) whenever the change depends
/// on the CURRENT state and more than one process may touch the same key
/// concurrently — e.g. `delonix-vm`'s `status()` (background metrics
/// refresh) racing a CLI `vm start`/`stop`/`create` on the same VM.
///
/// `f` returns `false` to abort the write (nothing changes). The item
/// returned is the final state (or the one read, if it aborted).
pub fn update<F>(&self, key: &str, f: F) -> Result<T>
where
    F: FnOnce(&mut T) -> bool,
{
    let _lock = FileLock::acquire(&self.lock_path(key))?;
    // Re-read UNDER the lock: between any earlier read and the `flock`
    // another process may have written; using a stale value would
    // reintroduce the lost update this exists to prevent.
    let mut v = self.load(key)?;
    if !f(&mut v) {
        return Ok(v);
    }
    self.save(key, &v)?;
    Ok(v)
}

write-atomic.code:
/// [`write_atomic`] with an explicit file mode, set **atomically at creation**.
///
/// For anything secret this is the only correct form. The alternative —
/// `fs::write` then `set_permissions` — creates the file under the ambient
/// umask and narrows it afterwards, leaving a window in which another local
/// user can open it. That is exactly the residual TOCTOU an earlier audit found
/// in the kubeconfig path and closed with `OpenOptions::mode`; the secret store
/// had the same shape and had not been converted.
pub fn write_atomic_mode(path: &Path, bytes: &[u8], mode: Option<u32>) -> Result<()> {
    use std::io::Write;
    use std::os::unix::fs::OpenOptionsExt;
    let dir = path.parent().unwrap_or_else(|| Path::new("."));
    let stem = path
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| "state".to_string());
    // Unique per WRITER (pid + sequence): a fixed temp name lets two processes —
    // or two threads of the CRI server — interleave their bytes in the same
    // temp, and then `rename` faithfully publishes the corruption.
    let seq = TMP_SEQ.fetch_add(1, Ordering::Relaxed);
    let tmp = dir.join(format!(".{stem}.{}.{seq}.tmp", std::process::id()));

    let write = || -> Result<()> {
        let mut opts = fs::OpenOptions::new();
        opts.write(true).create(true).truncate(true);
        if let Some(m) = mode {
            opts.mode(m); // atomic at creation — never widen-then-narrow
        }
        let mut f = opts.open(&tmp)?;
        f.write_all(bytes)?;
        // THE ORDER IS THE POINT: the content must be durable BEFORE the
        // directory entry that publishes it exists.
        f.sync_all()?;
        drop(f);
        fs::rename(&tmp, path)?;
        // And the rename itself must be durable, or a crash can lose the entry
        // even though the file's blocks are safely on disk.
        if let Ok(d) = fs::File::open(dir) {
            let _ = d.sync_all();
        }
        Ok(())
    };
    let r = write();
    if r.is_err() {
        let _ = fs::remove_file(&tmp); // never leave junk behind on failure
    }
    r
}

